from research_helpers import *
a=ev('https://www.sec.gov/Archives/edgar/data/1337905/000161577414000196/s100381_10k.htm','Historical2014 issuer portfolio identifies OX1/VP20629 indole3propionic acid, TauC3 antibody, CONJUMABA and licensed ANTISENILIN patent technology. Historical development/licensing evidence, not current2026 activity or approval.')
b=ev('https://www.sec.gov/Archives/edgar/data/1337905/000114420412056105/v325118_10k.htm','Historical2012 issuer separately identifies INN01 antibody, TOC01 oligomer antibody, RV03 dual-target vaccine and four proprietary technology platforms. Drug examples from other companies are NOT owned Intellect products.')
c=ev('https://www.sec.gov/Archives/edgar/data/1337905/000161577416005274/s103176_10q.htm','2016 issuer describes OX1 developed and sublicensed to ViroPharma/Shire. No current2026 continuation established; no approved therapy inferred.')
ps=[]
for name,desc,roles,aliases,attrs in [('Intellect OX1','Historical oral indole3propionic-acid antioxidant programme for neurodegeneration and Friedreich ataxia; licensed from NYU/SAMSF and sublicensed to ViroPharma/Shire.',['developer','licensee'],['VP-20629'],{'development_code':'OX1','active_molecule':'indole-3-propionic acid'}),('Intellect TauC3 therapeutic antibody','Historical licensed antibody against caspase-cleaved tau Asp421, investigated in Alzheimer models; not a claim of owning all commercial TauC3 laboratory reagents.',['licensee'],[],{'licensor':'Northwestern University','candidate_code':'TauC3'}),('CONJUMAB-A','Historical amyloid-beta-targeting antibody/melatonin conjugate for neurodegeneration and age-related macular degeneration.',['developer'],[],{'antibody_component':'IN-N01'}),('IN-N01','Historical humanized IgG4 amyloid-beta antibody candidate; also antibody component of separate CONJUMABA conjugate.',['developer'],[],{'form':'unconjugated antibody candidate'}),('TOC-01','Historical murine antibody selective for tau oligomers, licensed from Northwestern for potential tauopathy therapy.',['licensee'],['TOC-1'],{'licensor':'Northwestern University'}),('RV03','Historical bispecific vaccine candidate targeting amyloid beta and pathological delta tau.',['developer'],[],{})]:ps.append(p(name,desc,a,'unknown',roles=roles,aliases=aliases,attributes={**attrs,'evidence_scope':'historical issuer development; current status unverified'},evidence=[a,b,c]))
for name,desc in [('ANTISENILIN','Historical free-end-specific amyloid-beta antibody patent/licensing platform; patent licences do not establish ownership of licensees finished drugs.'),('CONJUMAB platform','Historical antibody/cytoprotective-small-molecule conjugation technology for proteinopathies.'),('OLIGOTOPE','Historical protein-oligomer-selective antibody discovery technology using stabilized cross-linked aggregates.'),('RECALL-VAX','Historical chimeric peptide vaccine technology targeting pathological-protein neoepitopes.')]:ps.append(p(name,desc,b,'unknown',typ='technology',sub='research_tools',attributes={'evidence_scope':'historical platform; current rights/activity unverified'}))
cs=[company('Intellect Neurosciences Inc',ps,[a,b,c],'Six historical therapeutic candidates and four platform identities reviewed in2012–2016 primary filings. All current statuses unknown; no contemporary availability or approval asserted. TauC3 therapeutic programme distinct from generic research antibody reagent identities. Licensees drugs and illustrative third-party ADCs excluded. Current corporate/rights continuity, N01OX2 historical naming and later dispositions still need verification.')]
(out/'batch-0122.json').write_text(json.dumps({'companies':cs},indent=2));print(len(ps))
